/// <summary>
/// Constructs the reference identities used to populate the <c>METTransferOrderExtractScreen</c> form.
/// </summary>
public  class METTransferOrderExtractScreenProcessor
{
    METTransferOrderExtractScreenTmp        metTransferOrderExtractScreenTmp;
    METTransferOrderExtractScreenParameters metTransferOrderExtractScreenParameters;
    InventTransferTable                     inventTransferTable;
    METInventTransferTableExt               metInventTransferTableExt;
    InventTransferLine                      inventTransferLine;
    METInventTransferLine                   metInventTransferLine;

    MetItemSiteSettingsSetup                itemSiteSettings;
    METWHSPhysDimUOMSite                    metWHSPhysDimUOMSite;
    METWHSPhysDimUOMSite                    metWHSPhysDimUOMSiteJoin;
    InventDim                               inventDim;

    ReqItemTable                            reqItemTable;
    METReqItemTable                         metReqItemTable;
    InventDim                               inventDimReq;
    METInventLocation                       metInventLocation;

    Factor                                  factor;
    InventQty                               cases;
    InventLocationId                        fromWarehouse;
    InventLocationId                        toWarehouse;
    METRoute                                route;
    InventTransferShipDate                  shippingDateFrom;
    InventTransferShipDate                  shippingDateTo;
    METOrderExtractStatus                   extracted;
    METFilterCodeone                        category;
    Volume                                  totalVolume;

    METTotalPallets                         totalPallets;

    Map                                     volumeMap;
    Map                                     itemTypeMap;
    MapEnumerator                           mapEnum;
    container                               transferOrderCon;

}

